<?php require_once __DIR__."/../config/auth.php";if(user())redirect("index.php");$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){try{check_csrf($_POST["csrf"]??"");$s=db()->prepare("SELECT * FROM users WHERE username=? AND is_active=1 LIMIT 1");$s->execute([trim($_POST["username"]??"")]);$u=$s->fetch();if($u&&password_verify($_POST["password"]??"",$u["password_hash"])){login_user($u);redirect("index.php");}$err=t("بيانات الدخول غير صحيحة","Invalid username or password");}catch(Throwable $e){$err=$e->getMessage();}}?><!doctype html><html lang="<?=lang()?>" dir="<?=lang()==="ar"?"rtl":"ltr"?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css"><title>RetailFlow</title></head><body class="center"><div class="card auth"><div class="logo">Retail<span>Flow</span></div><p>POS & Retail Management</p><?php if($err):?><div class="bad"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username<input name="username" value="admin" required autofocus></label><label>Password<input type="password" name="password" value="admin123" required></label><button class="btn primary full"><?=t("دخول","Login")?></button></form></div></body></html>